import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        byte[] data = System.in.readAllBytes();
        int p1 = 0;
        while (p1 < data.length && data[p1] != '\n') p1++;
        int p2 = p1 + 1;
        while (p2 < data.length && data[p2] != '\n') p2++;
        p2 = Math.min(p2, data.length);
        int la = p1, lb = Math.max(0, p2 - p1 - 1);
        byte[] out = new byte[la + lb + 1];
        int o = 0;
        for (int i = 0; i < Math.max(la, lb); i++) {
            if (i < la) out[o++] = data[i];
            if (i < lb) out[o++] = data[p1 + 1 + i];
        }
        out[o++] = '\n';
        System.out.write(out, 0, o);
        System.out.flush();
    }
}

