import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	parts := bytes.SplitN(data, []byte("\n"), 3)
	a, b := parts[0], parts[1]
	for i := 0; i < max(len(a), len(b)); i++ {
		if i < len(a) {
			w.WriteByte(a[i])
		}
		if i < len(b) {
			w.WriteByte(b[i])
		}
	}
	w.WriteByte('\n')
	_ = strconv.Itoa
}
